[special_theater] {
  "theater_configuration": [
    {
      "type": "IMAX巨幕影院",
      "capacity_suggestion": "300-400座",
      "screen_spec": "16.7×31.6米金属屏幕，32×22米银幕框",
      "feature_description": "大银幕沉浸式体验，适合深海探索、水下生态、滨水城市发展史等主题的科教电影，IMAX格式提供高清晰度与高动态范围，夜间开放可作为独立场馆入口。"
    },
    {
      "type": "多厅球幕影院",
      "capacity_suggestion": "200座（主厅）+ 120座（副厅）",
      "screen_spec": "主厅：23米直径倾斜式球幕；副厅：15米直径倾斜式球幕",
      "feature_description": "360°沉浸式天文科普主题，结合滨水夜景灯光投影，可分时段开放。副厅支撑VR天文课堂，主厅具备天体运动模拟功能。"
    },
    {
      "type": "4D动感影院",
      "capacity_suggestion": "60座×3厅（共180座）",
      "screen_spec": "4面投影融合弧形屏幕（12×5米×3屏）",
      "feature_description": "环境特效模拟（水雾、风、气味），适配青少年互动科普项目，如滨水生物进化模拟等，分时段轮播减少排队压力。"
    }
  ],
  "spatial_requirements": {
    "clear_height": "球幕厅：净高≥25米（含结构梁以下空间）；IMAX厅：净高≥12米；4D厅：净高≥6.5米（动感平台高度+3米）",
    "structure_span": "球幕厅采用双层钢桁架支撑，跨度≥28米；IMAX厅无柱净跨度≥35米；4D厅结构活荷载≥5kN/m²满足动态座椅需求",
    "acoustic_isolation": "采用双层中空砌体墙+吸音棉，STC≥55；球幕厅与展厅间设3米宽绿化隔离带；4D厅采用浮筑地面（弹簧减振器+橡胶垫层）"
  },
  "operational_layout": {
    "access_strategy": "影院区独立出入口设置于建筑西侧滨水步道，通过旋转闸机与票务系统连接，配套地下停车库直达通道，观众观影流线与博物馆主体流线分离，确保夜间运营独立性",
    "support_rooms": "IMAX机房设于夹层（100㎡含激光投影主机）；球幕机房与光学天文仪器库整合（150㎡）；4D厅旁配置眼镜消毒间（20㎡）及动态座椅维护工作间（30㎡），等候区采用流线型护栏设计+实时排号显示屏"
  }
}
